function urlFor(route){const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);return u.toString()}
async function go(p,route){let last;for(let i=0;i<4;i++){try{const r=await p.goto(urlFor(route),{waitUntil:'domcontentloaded',timeout:90000});if(r?.status()===200)return r;last=new Error('HTTP '+(r?.status()||0))}catch(e){last=e}await sleep([2500,5000,8000,12000][i])}throw last||new Error('navigation failed')}
async function waitStableSidebar(p){await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000});await p.waitForFunction(()=>{const s=document.querySelector('#MainContent .sq-refine-v3-sidebar');return !!s&&s.dataset.sqRefineV3TaxonomyNormalized==='true'},null,{timeout:12000}).catch(()=>{});let prev='';let stable=0;for(let i=0;i<20;i++){const now=await p.evaluate(()=>[...document.querySelectorAll('#MainContent .sq-refine-v3-sidebar > details.sq-refine-v3-group > summary')].map(x=>x.textContent.trim()).join('|')).catch(()=>'');if(now&&now===prev)stable++;else stable=0;prev=now;if(stable>=3)break;await sleep(150)}await sleep(300)}
async function inspect(p,mode){return p.evaluate(({mode})=>{const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0};const clean=s=>String(s||'').replace(/\s+/g,' ').trim();const m=document.querySelector('#MainContent');const side=[...m.querySelectorAll('.sq-refine-v3-sidebar')].find(vis);const groups=side?[...side.querySelectorAll(':scope > details.sq-refine-v3-group')].filter(vis).map(d=>({title:clean(d.querySelector(':scope > summary')?.textContent),inputs:d.querySelectorAll('input[type=checkbox]').length,invalid:[...d.querySelectorAll('input[type=checkbox]')].filter(i=>!i.dataset.target&&!i.dataset.filterName&&!i.dataset.sqPolishParam).length})):[];const grid=[...m.querySelectorAll('.sq-refine-v3-results .product-grid')].find(g=>vis(g)&&g.querySelector('a[href*="/products/"]'));const cards=grid?[...grid.querySelectorAll(':scope > *')].filter(x=>vis(x)&&x.querySelector('a[href*="/products/"]')):[];const rs=cards.slice(0,10).map(x=>x.getBoundingClientRect()),row=rs.length?rs.filter(r=>Math.abs(r.y-rs[0].y)<4).length:0;const native=[...m.querySelectorAll('.facets-block-wrapper--horizontal .facets__filters-wrapper,.facets-toggle__wrapper,theme-drawer#filters-drawer,.sq-global-refine-sidebar,.sq-maker-browser')].filter(vis).length;const legacy=[...m.querySelectorAll('[class*="button-tree"],[class*="category-grid"],[class*="type-grid"],[class*="branch-grid"],[class*="root-categories"],.sq-subcategory-section,.sq-subcategory-card')].filter(e=>vis(e)&&!e.closest('.sq-refine-v3-sidebar,.sq-refine-v3-results')).length;return{ready:m?.dataset.sqRefineV3Ready||'',error:m?.dataset.sqRefineV3Error||'',sidebar:!!side,position:side?getComputedStyle(side).position:'',title:clean(side?.querySelector('.sq-refine-v3-sidebar__title')?.textContent),groups,cards:cards.length,row,pageSizes:[...m.querySelectorAll('.sq-refine-v3-page-size input')].map(i=>i.value),native,legacy,overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+3,broken:[...m.querySelectorAll('img')].filter(i=>i.complete&&i.naturalWidth===0).length,mode};},{mode})}
async function runDevice(name,route,viewport){const b=await chromium.launch({headless:true});const c=await b.newContext({viewport,recordVideo:{dir:OUT,size:{width:name==='desktop'?1280:390,height:720}}});const p=await c.newPage();const pageErrors=[];p.on('pageerror',e=>pageErrors.push(String(e)));await p.addInitScript(()=>{window.__paint=[];const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0};const tick=()=>{const m=document.querySelector('#MainContent');if(m){window.__paint.push({t:Math.round(performance.now()),native:[...m.querySelectorAll('.facets-block-wrapper--horizontal .facets__filters-wrapper,.facets-toggle__wrapper,theme-drawer#filters-drawer,.sq-global-refine-sidebar,.sq-maker-browser')].some(vis),legacy:[...m.querySelectorAll('[class*="button-tree"],[class*="category-grid"],[class*="type-grid"],[class*="branch-grid"],[class*="root-categories"],.sq-subcategory-section,.sq-subcategory-card')].some(e=>vis(e)&&!e.closest('.sq-refine-v3-sidebar,.sq-refine-v3-results')),ready:m.dataset.sqRefineV3Ready||null})}if(performance.now()<5000)requestAnimationFrame(tick)};requestAnimationFrame(tick)});let status=0,error='';try{const r=await go(p,route);status=r.status();await waitStableSidebar(p)}catch(e){error=String(e)}let state=null,paint=[];try{state=await inspect(p,name);paint=await p.evaluate(()=>window.__paint||[])}catch{}const toggles=[];if(state?.sidebar){const titles=state.groups.map(g=>g.title).filter(Boolean);for(const title of titles){const d=p.locator('#MainContent .sq-refine-v3-sidebar > details.sq-refine-v3-group').filter({has:p.locator(':scope > summary',{hasText:title})}).first();if(await d.count()===0){toggles.push({title,ok:false,missing:true});continue}const s=d.locator(':scope > summary');let ok=false;try{const before=await d.evaluate(e=>e.open);await s.click();const mid=await d.evaluate(e=>e.open);await s.click();const end=await d.evaluate(e=>e.open);ok=mid!==before&&end===before}catch{}toggles.push({title,ok})}}await p.screenshot({path:path.join(OUT,`${slug(route)}-${name}.png`),fullPage:true}).catch(()=>{});const v=p.video();await p.close();await c.close();if(v){const src=await v.path().catch(()=>null);if(src)fs.copyFileSync(src,path.join(OUT,`${slug(route)}-${name}.webm`))}await b.close();return{name,status,error,state,badPaintCount:paint.filter(x=>x.native||x.legacy).length,toggles,pageErrors}}
function validate(route,d){const e=[];for(const dev of d){if(dev.status!==200)e.push(`${dev.name} HTTP ${dev.status}`);if(dev.error)e.push(`${dev.name} ${dev.error}`);const s=dev.state;if(!s){e.push(`${dev.name} no state`);continue}if(s.ready!=='true'||s.error)e.push(`${dev.name} V3 not ready`);if(!s.sidebar||s.title.toUpperCase()!=='REFINE PRODUCTS')e.push(`${dev.name} sidebar/header`);if(!s.cards)e.push(`${dev.name} no products`);if(dev.name==='desktop'&&s.row!==3)e.push(`desktop row ${s.row}`);if(dev.name==='mobile'&&s.row!==2)e.push(`mobile row ${s.row}`);if(dev.name==='desktop'&&s.position!=='sticky')e.push(`desktop sidebar ${s.position}`);if(dev.name==='mobile'&&s.position==='sticky')e.push('mobile sidebar sticky');if(s.pageSizes.join(',')!=='50,100,250')e.push(`${dev.name} page sizes ${s.pageSizes.join(',')}`);if(s.native||s.legacy||s.overflow||s.broken)e.push(`${dev.name} contamination/geometry`);if(dev.badPaintCount)e.push(`${dev.name} bad first-paint ${dev.badPaintCount}`);if(dev.toggles.some(x=>!x.ok))e.push(`${dev.name} accordion toggle`);if(s.groups.some(g=>g.inputs<1||g.invalid>0))e.push(`${dev.name} empty/invalid group`);const labels=s.groups.map(g=>g.title);if(!labels.includes('Shop by Type'))e.push(`${dev.name} missing Shop by Type`);if(!labels.includes('Shop by Manufacturers'))e.push(`${dev.name} missing Shop by Manufacturers`);if(route==='/collections/literature'){if(!labels.some(x=>/Shop by Author/i.test(x)))e.push(`${dev.name} books author`);if(!labels.some(x=>/Publisher/i.test(x)))e.push(`${dev.name} books publisher`)}if(route==='/collections/firearm-accessories'&&!labels.some(x=>/Firearm Make|Make \/ Model/i.test(x)))e.push(`${dev.name} firearm make/model`)}return e}
const report={shard:SHARD,shards:SHARDS,theme:THEME,routes:[],failures:[]};
for(const [name,route,type] of mine){console.log(`START ${name}`);if(type==='legacy'){const b=await chromium.launch();const c=await b.newContext({viewport:{width:1440,height:1000},recordVideo:{dir:OUT,size:{width:1280,height:720}}});const p=await c.newPage();let status=0,error='';try{const r=await go(p,route);status=r.status();await p.waitForTimeout(1200)}catch(e){error=String(e)}const state=await p.evaluate(()=>({v3:!!document.querySelector('[data-sq-refine-v3]'),side:!!document.querySelector('.sq-refine-v3-sidebar')})).catch(()=>({v3:true,side:true}));await p.screenshot({path:path.join(OUT,`${slug(route)}-desktop.png`),fullPage:true}).catch(()=>{});const v=p.video();await p.close();await c.close();if(v){const src=await v.path().catch(()=>null);if(src)fs.copyFileSync(src,path.join(OUT,`${slug(route)}-desktop.webm`))}await b.close();const errors=[];if(status!==200)errors.push(`HTTP ${status}`);if(error)errors.push(error);if(state.v3||state.side)errors.push('unexpected V3 UI');const row={name,route,type,pass:!errors.length,errors,state};report.routes.push(row);if(errors.length)report.failures.push(...errors.map(x=>`${name}: ${x}`));console.log(`${row.pass?'PASS':'FAIL'} ${name}${errors.length?' :: '+errors.join(' | '):''}`);continue}const desktop=await runDevice('desktop',route,{width:1440,height:1000});const mobile=await runDevice('mobile',route,{width:390,height:844});const errors=validate(route,[desktop,mobile]);const row={name,route,type,pass:!errors.length,errors,desktop,mobile};report.routes.push(row);if(errors.length)report.failures.push(...errors.map(x=>`${name}: ${x}`));console.log(`${row.pass?'PASS':'FAIL'} ${name}${errors.length?' :: '+errors.join(' | '):''}`)}
fs.writeFileSync(path.join(OUT,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({shard:SHARD,pass:report.routes.filter(r=>r.pass).length,fail:report.routes.filter(r=>!r.pass).length,failures:report.failures},null,2));if(report.failures.length)process.exitCode=2;